/bin/bash -lc "node --input-type=module <<'JS'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { once } from 'node:events';
import assert from 'node:assert/strict';
const directory = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], {
  env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'workboard.sqlite') },
  detached: true, stdio: ['ignore', 'pipe', 'inherit'],
});
try {
  const port = await new Promise((resolve, reject) => {
    let output = '';
    const timeout = setTimeout(() => reject(new Error('Startup timeout')), 10000);
    child.stdout.on('data', (chunk) => {
      output += chunk;
      const match = output.match(/Workboard listening on port (\\d+)/);
      if (match) { clearTimeout(timeout); resolve(match[1]); }
    });
    child.once('exit', () => { clearTimeout(timeout); reject(new Error('Server exited before readiness')); });
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  assert.equal(response.status, 200);
  assert.deepEqual(await response.json(), { status: '"'ok' });
  console.log('npm start and GET /health passed');
} finally {
  const stopped = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await stopped;
  await rm(directory, { recursive: true, force: true });
}
JS"

